#!/bin/bash
set -x

# SFT training with trajectories generated by teacher model
SFT_DATA_DIR="$HOME/data/verl-agent/webshop_sft"
SAVE_PATH="$HOME/models/webshop_qwen2.5_1.5b_sft"

torchrun --standalone --nnodes=1 --nproc_per_node=2 \
    -m verl.trainer.fsdp_sft_trainer \
    data.train_files=$SFT_DATA_DIR/train.parquet \
    data.val_files=$SFT_DATA_DIR/val.parquet \
    data.multiturn.enable=True \
    data.multiturn.messages_key=messages \
    data.max_length=4096 \
    data.truncation=right \
    data.micro_batch_size_per_gpu=1 \
    data.train_batch_size=16 \
    model.partial_pretrain=Qwen/Qwen2.5-1.5B-Instruct \
    model.enable_gradient_checkpointing=True \
    model.trust_remote_code=True \
    optim.lr=1e-5 \
    trainer.default_local_dir=$SAVE_PATH \
    trainer.project_name=webshop-sft \
    trainer.experiment_name=qwen2.5-1.5b-sft \
    trainer.logger=['console'] \
    trainer.total_epochs=3
